module ping_pong (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] n,\n    input wire [2:0] k,\n    input wire [63:0] adj,\n    input wire [7:0] s_mask,\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] IDLE            = 4'd0;\n    localparam [3:0] INIT            = 4'd1;\n    localparam [3:0] CHECK_S         = 4'd2;\n    localparam [3:0] CHECK_S_DONE    = 4'd3;\n    localparam [3:0] PREP_ENUM_T     = 4'd4;\n    localparam [3:0] ENUM_T_SIZE     = 4'd5;\n    localparam [3:0] ENUM_T_SUBSET   = 4'd6;\n    localparam [3:0] CHECK_SUBSET    = 4'd7;\n    localparam [3:0] FLOYD_COMPUTE   = 4'd8;\n    localparam [3:0] RESULTS         = 4'd9;\n    localparam [3:0] FAIL            = 4'd10;\n    localparam [3:0] FINISH          = 4'd11;\n\n    reg [3:0] state, next_state;\n    reg [7:0] s_set;            // S set (original DQ)\n    reg [7:0] t_set;            // T = ~S (players available to remove)\n    reg [7:0] current_subset;   // Current subset R of T being checked\n    reg [7:0] vertices_set;     // Current V' = (S | T) \\ R = S | (T \\ R)\n    reg cyclic;                // Cycle detection flag\n    reg [2:0] t_size;          // Current t value being checked\n    reg [2:0] i, j, m;         // Loop counters for Floyd-Warshall\n    reg [63:0] reach;          // Reachability matrix (8x8)\n    reg [63:0] curr_edges;     // Current edges for V'\n    reg [7:0] valid_players;   // Players present in current subgraph\n    reg kz_flag;               // Flag for k=0 case\n\n    // State register and control\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            s_set <= 8'd0;\n            t_set <= 8'd0;\n            current_subset <= 8'd0;\n            vertices_set <= 8'd0;\n            cyclic <= 1'b0;\n            t_size <= 3'd0;\n            i <= 3'd0;\n            j <= 3'd0;\n            m <= 3'd0;\n            reach <= 64'd0;\n            curr_edges <= 64'd0;\n            valid_players <= 8'd0;\n            kz_flag <= 1'b0;\n        end else begin\n            state <= next_state;\n            // Deassert done after one cycle\n            if (state == FINISH) done <= 1'b0;\n            case (state)\n                INIT: begin\n                    s_set <= s_mask & ((1 << n) - 1);\n                    t_set <= ((1 << n) - 1) & ~s_mask;\n                    valid_players <= s_mask & ((1 << n) - 1);\n                end\n                CHECK_S: curr_edges <= adj;\n                CHECK_SUBSET: begin\n                    vertices_set <= (s_set | t_set) & ~current_subset;\n                    // Mask the adjacency matrix to current vertices\n                    for (i = 0; i < 8; i = i + 1) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if (!vertices_set[i] || !vertices_set[j])\n                                curr_edges[i*8 + j] <= 1'b0;\n                            else\n                                curr_edges[i*8 + j] <= adj[i*8 + j];\n                        end\n                    end\n                end\n                FLOYD_COMPUTE: begin\n                    if (m < 3'd7) begin\n                        for (i = 0; i < 8; i = i + 1) begin\n                            for (j = 0; j < 8; j = j + 1) begin\n                                reach[i*8 + j] <= (reach[i*8 + j] ||\n                                    (reach[i*8 + m] && reach[m*8 + j]));\n                            end\n                        end\n                        m <= m + 3'd1;\n                    end\n                end\n                default: ;\n            endcase\n        end\n    end\n\n    // Main state machine\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                if (start) next_state = INIT;\n            end\n            INIT: next_state = CHECK_S;\n            CHECK_S: next_state = CHECK_SUBSET;  // Reuse logic for checking S\n            CHECK_SUBSET: next_state = FLOYD_COMPUTE;\n            FLOYD_COMPUTE: begin\n                if (m >= (n - 3'd1)) next_state = CHECK_S_DONE;\n                else next_state = FLOYD_COMPUTE;\n            end\n            CHECK_S_DONE: begin\n                if (cyclic) next_state = (k == 3'd0) ? FAIL : PREP_ENUM_T;\n                else begin\n                    if (k == 3'd0) next_state = RESULTS;\n                    else next_state = kz_flag ? RESULTS : PREP_ENUM_T;\n                end\n            end\n            PREP_ENUM_T: begin\n                if (t_set == 8'd0) next_state = FAIL;  // No players to remove\n                else begin\n                    t_size <= 3'd0;\n                    current_subset <= 8'd0;\n                    next_state = ENUM_T_SIZE;\n                end\n            end\n            ENUM_T_SIZE: begin\n                if (t_size >= k) next_state = FAIL;\n                else if (current_subset == (t_set + 8'd1)) begin  // Subset overflow\n                    t_size <= t_size + 3'd1;\n                    current_subset <= 8'd0;\n                end else begin\n                    // Check if current_subset is a valid subset of T with size t_size\n                    if ((current_subset & t_set) == current_subset &&\n                        $countones(current_subset) == t_size) begin\n                        next_state = ENUM_T_SUBSET;\n                    end else begin\n                        current_subset <= current_subset + 8'd1;\n                    end\n                end\n            end\n            ENUM_T_SUBSET: next_state = CHECK_SUBSET;\n            RESULTS: begin\n                if (!cyclic) next_state = FINISH;\n                else next_state = (current_subset + 8'd1) <= (1 << n) ?\n                                   ENUM_T_SIZE : PREP_ENUM_T;\n            end\n            FAIL: next_state = FINISH;\n            FINISH: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Cycle detection logic\n    always @(*) begin\n        cyclic = 1'b0;\n        for (integer a = 0; a < 8; a = a + 1) begin\n            if (reach[a*8 + a]) cyclic = 1'b1;\n        end\n    end\n\n    // Result and done handling\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            result <= 8'd0;\n            done <= 1'b0;\n        end else if (state == FINISH) begin\n            done <= 1'b1;\n            if (state == FAIL || result == 8'd255)\n                result <= 8'd255;\n            else\n                result <= t_size;\n        end\n    end\n\n    // Population counter function (synthesis pragma for Icarus compatibility)\n    function automatic integer $countones(input [7:0] vec);\n        integer count;\n        begin\n            count = 0;\n            for (integer l = 0; l < 8; l = l + 1) begin\n                if (vec[l]) count = count + 1;\n            end\n            $countones = count;\n        end\n    endfunction\n\nendmodule